// Self-closing form first: `<testMethod …/>` has no body; otherwise `[^>]*` would eat the `/`.
const METHOD = /<(?:\w+:)?testMethod\b([^>]*?)\/>|<(?:\w+:)?testMethod\b([^>]*)>([\s\S]*?)<\/(?:\w+:)?testMethod>/g;
